export interface ProcedureStep {
  id: string;
  section: string;
  title: string;
  control: string;
  action: string;
  expect: string;
  caution?: string;
  evidence: string;
  /** Cockpit panels shown for this step (catalogue ids), the acting one first. */
  panels: string[];
  /** The control move that completes the step: `<panel>.<control>` to a position; `hold` ms it must be held. */
  do?: { control: string; to: string; on?: 'press' | 'release'; hold?: number };
  /** More moves the step needs (any order) besides `do`. */
  also?: { control: string; to: string; on?: 'press' | 'release'; hold?: number }[];
  /** Check steps: the confirm button's label. */
  confirm?: string;
  /** Turn a knob until the readout shows `to`, `per` degrees a click. */
  turn?: { control: string; to: number; per: number };
  /** Keys typed in order (control ids, `icp.key-N` or `icp.entr`), each pressed in turn, with the DED page after each. */
  type?: { keys: string[]; pages: string[] };
  /** Rings the step text can show: `{{phrase|k}}` in `action`/`expect` shows hint k. A hint is comma-separated targets `panel.indicator`, `panel.control` or `panel.indicator@row` (a DED row, 0–4). */
  hints?: string[];
  /** A cross-check question: the reader picks one answer; `answer` indexes `options`. */
  ask?: { question: string; options: string[]; answer: number; right: string; wrong: string };
  /** Encyclopedia records this step sends the reader to (slugs, shown as links). */
  links?: { slug: string; label: string; anchor?: string }[];
}
export interface AircraftProcedure {
  id: string;
  slug: string;
  airframe: string;
  title: string;
  objective: string;
  applicability: string;
  status: 'public-preview' | 'review-only';
  simVersion: string;
  /** Which script drives the cockpit panels. */
  model: 'engine-start' | 'tacan-navigation' | 'steerpoint-entry' | 'before-taxi' | 'before-takeoff' | 'hts' | 'hts-targeting' | 'harm-shot' | 'maverick-pre';
  /** The scenario shown above the steps, and the closing heading. */
  intro: string;
  description: string;
  complete: string;
  /** Slug of the procedure that follows this one; the closing heading links to it. */
  next?: string;
  /** The Sources section's text. */
  sources: string;
  steps: ProcedureStep[];
  /** Cockpit positions at the start, where they differ from each control's cold-and-dark `initial`. */
  initial?: Record<string, string>;
}
